(function(){
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='murumehed.simple.v3',PREVIOUS='murumehed.simple.v2',OLD='murumehed.winter.plan.v1',colors=['#247448','#397fbd','#985fba','#d28b27','#ce5d71','#6d842c'];
const sites=window.SOURCE_DATA.sites,byId=Object.fromEntries(sites.map(s=>[s.id,s]));
const work=s=>s.work==='Ainult käsitöö'?'hand':s.work==='Ainult masinatöö'?'machine':'both';
const kind=s=>work(s)==='hand'?'Käsitöö':work(s)==='machine'?'Masinatöö':'Masina- ja käsitöö';
const group=s=>s.deadline<='08:30'?'early':s.deadline<='10:00'?'mid':'late';
const dur=n=>n===null?'Määra tööaeg':new Intl.NumberFormat('et-EE',{maximumFractionDigits:1}).format(n)+' min';
const hours=n=>Math.floor(Math.round(n)/60)+' h '+(Math.round(n)%60)+' min';
const shortAddress=a=>a.split(',').map(v=>v.trim()).filter(v=>! /^(Eesti|Estonia|Tartumaa|Tartu maakond)$/i.test(v)).join(', ');
const planNames={weekday:'Tööpäev',weekend:'Libedaring / sissepääsud'};
const isAssociation=s=>/korteriühistu|\bKÜ\b/i.test(s.client)||/^KÜ(?:\s|$)/i.test(s.client);
const weekendRank=s=>isAssociation(s)?0:s.deadline<='08:00'?2:1;
function weekendOrder(c){c.stops.sort((a,b)=>weekendRank(byId[a.id])-weekendRank(byId[b.id]));}
function fresh(){return {version:2,objectRevision:1,crews:Array.from({length:6},(_,i)=>({name:i===5?'Käsitöö':'Masin '+(i+1),stops:[]})),notes:{},coords:{}};}
function updateObjects(p){
if(p){
if(Array.isArray(p.crews))for(const c of p.crews)if(Array.isArray(c.stops))c.stops=c.stops.filter(st=>st.id!=='T26-070');
if(p.notes)delete p.notes['T26-070'];
if(p.coords&&typeof p.coords==='object'){const known=new Set(sites.flatMap(s=>s.addresses));for(const a of Object.keys(p.coords))if(!known.has(a))delete p.coords[a];}
}
if(!p||p.objectRevision===1)return p;
if(!Array.isArray(p.crews)||!p.notes||!p.coords)return p;
for(const c of p.crews){if(!Array.isArray(c.stops))continue;const at=c.stops.findIndex(st=>st.id==='T26-052');if(at>=0&&!c.stops.some(st=>st.id==='T26-052-K'))c.stops.splice(at+1,0,{id:'T26-052-K',minutes:null});}
if(p.notes['T26-052']&&!p.notes['T26-052-K'])p.notes['T26-052-K']=p.notes['T26-052'];


p.objectRevision=1;return p;
}
function validate(p){updateObjects(p);if(!p||p.version!==2||!Array.isArray(p.crews)||![4,6].includes(p.crews.length)||!p.notes||!p.coords)throw Error('See pole sobiv ringiplaan.');p.crews.forEach((c,i)=>{if(c.startTime!==undefined&&c.startTime!==''&&!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(c.startTime))throw Error('Vigane algusaeg.');if(c.startDay!==undefined&&!['same','sat','sun'].includes(c.startDay))throw Error('Vigane alguspäev.');if(typeof c.name!=='string'||!c.name.trim()||c.name.length>80||!Array.isArray(c.stops))throw Error('Vigane masin.');let own=new Set();c.stops.forEach(st=>{if(!byId[st.id]||own.has(st.id)||st.minutes!==null&&(!Number.isFinite(st.minutes)||st.minutes<0||st.minutes>1440))throw Error('Korduv objekt või vigane tööaeg.');if(p.crews.length===6&&i<5&&work(byId[st.id])==='hand')throw Error('Käsitöö objekt on masinaringis.');own.add(st.id);});});for(const n of Object.values(p.notes))if(typeof n!=='string'||n.length>10000)throw Error('Vigane märkus.');const addrs=new Set(sites.flatMap(s=>s.addresses));for(const [a,c]of Object.entries(p.coords))if(!addrs.has(a)||!Array.isArray(c)||c.length!==2||!c.every(Number.isFinite)||Math.abs(c[0])>90||Math.abs(c[1])>180)throw Error('Vigane kaardipunkt.');return p;}
function migrate(p){const n=fresh();p.crews?.slice(0,6).forEach((c,i)=>{n.crews[i].name=c.name||n.crews[i].name;for(const st of c.stops||[]){if(!byId[st.id]||i<5&&work(byId[st.id])==='hand')continue;n.crews[i].stops.push({id:st.id,minutes:i===5&&work(byId[st.id])!=='hand'?null:p.jobs?.[st.id]?.minutes??byId[st.id].minutes});}});n.coords=p.coords||{};delete n.objectRevision;return validate(n);}
function fourRoutes(p){
if(p.crews.length===6){
p.archivedCrews=JSON.parse(JSON.stringify(p.crews.slice(4)));
p.crews=p.crews.slice(0,4);
}
return p;
}
function bundleFrom(p){const weekday=validate(p),weekend=JSON.parse(JSON.stringify(p));weekend.crews.forEach(c=>{c.startTime='';});return {version:3,plans:{weekday,weekend:fourRoutes(weekend)}};}
function validateBundle(b){if(!b||b.version!==3||!b.plans)throw Error('See pole sobiv ringiplaan.');validate(b.plans.weekday);validate(b.plans.weekend);fourRoutes(b.plans.weekend);if(b.plans.weekday.crews.length!==6)throw Error("Tööpäeval peab olema kuus ringi.");return b;}
function readPlan(p){return p.version===3?validateBundle(p):bundleFrom(p.version===1?migrate(p):validate(p));}
let bundle=bundleFrom(fresh()),mode='weekday',state=bundle.plans.weekday,active=0,shown=Array(6).fill(true),map,layer,bounds=[],selected=null,restoreMessage='';
try{const saved=localStorage.getItem(KEY),previous=localStorage.getItem(PREVIOUS),old=localStorage.getItem(OLD);if(saved)bundle=readPlan(JSON.parse(saved));else if(previous||old){bundle=readPlan(JSON.parse(previous||old));restoreMessage='Tööpäeva plaan säilitatud. Libedaringiks on eraldi koopia.';}state=bundle.plans[mode];}catch{try{const raw=localStorage.getItem(KEY);if(raw)localStorage.setItem(KEY+'.failed',raw);}catch{}restoreMessage='Varasema plaani taastamine ei õnnestunud. Algandmed on alles.';}
function switchPlan(next){if(!planNames[next])return;mode=next;state=bundle.plans[mode];active=0;shown=Array(state.crews.length).fill(true);$('service-filter').checked=mode==='weekend';seedCoords();save();render();renderMap(true);}
function seedCoords(){for(const s of sites)for(const [a,p] of Object.entries(s.coords||{}))if(!state.coords[a])state.coords[a]=p;}
seedCoords();
function message(s){$('status').textContent=s;}
function save(){try{validateBundle(bundle);localStorage.setItem(KEY,JSON.stringify(bundle));message('Salvestatud sellesse brauserisse');}catch(e){message('Salvestamine ebaõnnestus. Salvesta plaan failina.');}}
const owners=id=>state.crews.map((c,i)=>c.stops.some(st=>st.id===id)?i:-1).filter(i=>i>=0);
function total(c){return {minutes:c.stops.reduce((n,st)=>n+(st.minutes??0),0),missing:c.stops.filter(st=>st.minutes===null).length};}
function filtered(){const q=$('search').value.toLocaleLowerCase('et');return sites.filter(s=>(!q||[s.client,...s.addresses,s.phone,s.id].join(' ').toLocaleLowerCase('et').includes(q))&&(!$('deadline').value||group(s)===$('deadline').value)&&(!$('service-filter').checked||work(s)!=='machine')&&(!$('free').checked||!owners(s.id).length));}
function add(id){let s=byId[id],c=state.crews[active];if(c.stops.some(st=>st.id===id))return;if(mode==='weekday'&&active<5&&work(s)==='hand'){message('See on ainult käsitöö objekt. Lisa see käsitöö ringile.');return;}c.stops.push({id,minutes:active===5&&work(s)!=='hand'?null:s.minutes});save();render();}
function render(){$('plan-tabs').innerHTML=Object.entries(planNames).map(([k,v])=>'<button data-plan="'+k+'" aria-pressed="'+(mode===k)+'" class="'+(mode===k?'selected':'')+'">'+v+'</button>').join('');$('plan-hint').textContent=mode==='weekend'?'Libedustõrje ning sissepääsude ja kõnniteede lumetõrje.':'Tööpäeva ringid';$('weekend-sort').hidden=true;$('start-day').hidden=true;renderMachines();renderList();renderRoute();renderMap();}
function renderMachines(){$('machines').className=mode==='weekend'?'four-routes':'';$('archive-routes').hidden=mode!=='weekend'||!state.archivedCrews?.some(c=>c.stops.length);$('map-heading-text').textContent=mode==='weekend'?'Neli ringi. Üks kaart.':'Kuus ringi. Üks kaart.';$('machines').innerHTML=state.crews.map((c,i)=>{let t=total(c);return '<button class="machine '+(active===i?'active':'')+'" style="--c:'+colors[i]+'" data-machine="'+i+'" aria-pressed="'+(active===i)+'"><strong>'+esc(c.name)+'</strong><span>'+c.stops.length+' objekti · '+hours(t.minutes)+(t.missing?' + ?':'')+'</span><div class="load"><i style="width:'+Math.min(t.minutes/540*100,100)+'%"></i></div></button>';}).join('');$('legend').innerHTML=state.crews.map((c,i)=>'<label style="--c:'+colors[i]+'"><input type="checkbox" data-show="'+i+'" '+(shown[i]?'checked':'')+'><i></i>'+esc(c.name)+'</label>').join('');}
function renderList(){const found=filtered();$('count').textContent=found.length+' / '+sites.length;$('list').innerHTML=found.map(s=>{let os=owners(s.id),inActive=os.includes(active),disabled=mode==='weekday'&&active<5&&work(s)==='hand';return '<div class="object"><button class="title" data-detail="'+s.id+'">'+esc(shortAddress(s.addresses[0]))+(s.addresses.length>1?' +'+(s.addresses.length-1):'')+'</button><div class="sub">'+esc(s.client)+' · '+dur(s.minutes)+'</div><div class="sub">'+(os.length?os.map(i=>'<span style="color:'+colors[i]+'">'+esc(state.crews[i].name)+'</span>').join(' + '):kind(s))+'</div><div class="object-bottom"><span class="badge '+group(s)+'">Kuni '+s.deadline+'</span><button data-add="'+s.id+'" '+(inActive||disabled?'disabled':'')+'>'+(inActive?'Ringis':disabled?'Käsitöö':os.length?'Lisa ka siia':'+ Lisa')+'</button></div></div>';}).join('')||'<p class="empty">Sobivaid objekte pole.</p>';}
function renderSummary(){const c=state.crews[active],t=total(c);$('crew-name').value=c.name;$('summary').innerHTML='<b>'+hours(t.minutes)+'</b> tööaega / 9 h'+(t.missing?' <span class="warning">· '+t.missing+' tööaega lisada</span>':'')+'<div class="load" style="--c:'+colors[active]+'"><i style="width:'+Math.min(t.minutes/540*100,100)+'%"></i></div><div class="sub">Tööaeg objektidel. '+(t.minutes>540?'Üle 9 tunni: '+hours(t.minutes-540)+'.':'')+'</div>';
}
function renderRoute(){const c=state.crews[active];renderSummary();$('start-time').value=c.startTime||'';$('start-day').value=c.startDay==='sun'?'sun':'sat';
$('route').innerHTML=c.stops.length?c.stops.map((st,i)=>{let s=byId[st.id];return '<div class="stop" draggable="true" data-drag="'+i+'" style="--c:'+colors[active]+'"><span class="order">'+(i+1)+'</span><div><button class="title" data-detail="'+s.id+'">'+esc(s.addresses.map(shortAddress).join(' / '))+'</button><div class="sub">'+esc(s.client)+' · <strong>kuni '+s.deadline+'</strong></div><div class="duration"><input aria-label="Tööaeg '+s.id+'" data-minutes="'+s.id+'" type="number" min="0" max="1440" step="0.1" placeholder="?" value="'+(st.minutes??'')+'"> min'+(active===5&&work(s)!=='hand'?' · käsitöö / abi':'')+'</div></div><div class="moves"><button data-up="'+i+'" aria-label="Üles '+s.id+'" '+(!i?'disabled':'')+'>↑</button><button data-down="'+i+'" aria-label="Alla '+s.id+'" '+(i===c.stops.length-1?'disabled':'')+'>↓</button><button data-remove="'+s.id+'" aria-label="Eemalda '+s.id+'">×</button></div></div>';}).join(''):'<div class="empty"><h2>Koosta '+esc(c.name)+' ring</h2>Lisa alt objektid ja pane need järjekorda.</div>';}
function renderMap(fit=false){if(!window.L){$('map').textContent='Kaart ei laadinud. Ringide nimekirjad töötavad edasi.';return;}if(!map){map=L.map('map').setView([58.37,26.72],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);layer=L.layerGroup().addTo(map);}layer.clearLayers();bounds=[];let missing=0;const occupied={};
function marker(s,a,p,color,label){if(!p){missing++;return;}bounds.push(p);const pk=p.join(','),offset=occupied[pk]||0;occupied[pk]=offset+1;const m=L.marker(p,{title:shortAddress(a),icon:L.divIcon({className:'',html:'<div class="marker '+(label?'':'unassigned-marker')+'" style="background:'+color+'">'+label+'</div>',iconSize:label?[27,27]:[12,12],iconAnchor:label?[13-offset*20,13]:[6,6]})}).addTo(layer);let pop=document.createElement('div');pop.innerHTML='<b>'+esc(shortAddress(a))+'</b><br>'+esc(s.client)+'<br>Kuni '+s.deadline+' · '+dur(s.minutes)+'<br><button class="map-detail">Detailid</button> <button class="map-add">Lisa: '+esc(state.crews[active].name)+'</button>';pop.querySelector('.map-detail').onclick=()=>openDetail(s.id);pop.querySelector('.map-add').onclick=()=>{add(s.id);map.closePopup();};m.bindPopup(pop);}
if($('unassigned').checked)for(const s of filtered())if(!owners(s.id).length)for(const a of s.addresses)marker(s,a,state.coords[a],'#9aa69a','');
state.crews.forEach((c,i)=>{if(!shown[i])return;let prev=null;for(const [n,st]of c.stops.entries()){let s=byId[st.id];for(const a of s.addresses){let p=state.coords[a];marker(s,a,p,colors[i],String(n+1));if(p&&prev)L.polyline([prev,p],{color:colors[i],weight:i===active?4:2.5,opacity:.8,dashArray:'7 5'}).addTo(layer);prev=p||null;}}});
$('map-status').textContent=missing?missing+' aadressipunkti asukoht puudub. Nende kaardile lisamiseks impordi algkaardi KML.':'';if(fit&&bounds.length)map.fitBounds(bounds,{padding:[25,25],maxZoom:15});}
function openDetail(id){selected=id;const s=byId[id];$('detail-content').innerHTML='<small>'+esc(s.id)+'</small><h2>'+esc(s.client)+'</h2><p>'+s.addresses.map(a=>esc(shortAddress(a))+' <a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(a)+'">↗</a>').join('<br>')+'</p><div class="detail-meta"><b>Kuni '+s.deadline+'</b> · '+kind(s)+'<br>Algne töömaht: '+dur(s.minutes)+'<br>Telefon: '+esc(s.phone||'—')+'<br>E-post: '+esc(s.email||'—')+'<br>Periood: '+esc(s.period||'—')+'</div><h3>Töö ja ligipääs</h3><p>'+esc(s.notes||'Lisamärkusi pole.')+'</p><label>Lisajuhis juhile (nt värava avamine)<textarea id="driver-note">'+esc(state.notes[id]||'')+'</textarea></label><button id="save-note" class="primary">Salvesta juhis</button><p class="sub">Masina- ja käsitöö kuuluvad mõlemad objekti juurde. Sama objekti saab lisada mitme masina ja käsitöö ringile. Iga ringi tööaega saab muuta eraldi.</p>';$('detail').showModal();}

function driverWork(i,s){return mode==='weekend'?(i===5?'Libedustõrje ja käsitöö sissepääsudel / kõnniteedel':'Libedustõrje; sissepääsude ja kõnniteede lumetõrje'):(i===5?'Käsitöö / abi':kind(s));}
async function exportAll(archived=false){
const button=$('print-all');if(button.disabled)return;
button.disabled=true;message('Koostan PDF-faile…');
const snapshot=JSON.parse(JSON.stringify(state));if(archived)snapshot.crews=snapshot.archivedCrews||[];const label=planNames[mode],routeMode=mode;
try{const files=snapshot.crews.map((c,i)=>({name:c.name,start:c.startTime||'kellaaeg määramata',color:colors[i],rows:c.stops.map((st,n)=>{const s=byId[st.id];return [String(n+1),s.addresses.map(shortAddress).join(' / ')+'\n'+s.client,s.deadline,[driverWork(i,s),s.notes,snapshot.notes[s.id]?'Juhis: '+snapshot.notes[s.id]:'',s.phone?'Tel '+s.phone:''].filter(Boolean).join('\n')];})}));
const blob=await window.DriverExport.zip(files,label);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(routeMode==='weekend'?'libedaring-sissepaasud':'toopaev')+(archived?'-varasemad-ringid':'')+'-juhile.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);message('ZIP valmis: '+snapshot.crews.length+' ringi PDF-id.');
}catch(e){message('PDF-ide loomine ebaõnnestus. Proovi uuesti.');console.error(e);}finally{button.disabled=false;}
}
function printSheet(){const c=state.crews[active];const beginning=(c.startTime||'kellaaeg määramata');$('print-sheet').innerHTML='<div class="print-heading" style="--route-color:'+colors[active]+'"><small>MURUMEHED · '+planNames[mode].toLocaleUpperCase('et')+'</small><h1>'+esc(c.name)+'</h1><div>Algus: <b>'+esc(beginning)+'</b> &nbsp; · &nbsp; '+c.stops.length+' objekti</div></div><table><thead><tr><th>#</th><th>Objekt / aadress</th><th>Hiljemalt</th><th>Töö ja ligipääs</th></tr></thead><tbody>'+c.stops.map((st,i)=>{const s=byId[st.id];return '<tr><td><span class="print-number" style="color:'+colors[active]+'">'+(i+1)+'</span></td><td><b>'+s.addresses.map(a=>esc(shortAddress(a))).join('<br>')+'</b><div class="print-client">'+esc(s.client)+'</div></td><td><span class="print-deadline">'+s.deadline+'</span></td><td><b>'+driverWork(active,s)+'</b>'+(s.notes?'<p>'+esc(s.notes)+'</p>':'')+(state.notes[s.id]?'<p class="print-instruction"><b>Juhis:</b> '+esc(state.notes[s.id])+'</p>':'')+(s.phone?'<div class="print-phone">Tel '+esc(s.phone)+'</div>':'')+'</td></tr>';}).join('')+'</tbody></table>';window.print();}
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function importCoords(file){if(file.size>10e6)throw Error('KML on liiga suur.');const text=await file.text();if(/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('KML vorming ei sobi.');const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw Error('KML on vigane.');let count=0;const all=(el,n)=>Array.from(el.getElementsByTagNameNS('*',n)),norm=a=>a.toLocaleLowerCase('et').replace(/,?\s*eesti/g,'').replace(/\s+/g,' ').trim();for(const pm of all(xml,'Placemark')){const attrs=Object.fromEntries(all(pm,'Data').map(d=>[d.getAttribute('name'),all(d,'value')[0]?.textContent||''])),name=all(pm,'name')[0]?.textContent||'',address=attrs.Aadress||name.replace(/^\d\d:\d\d\s*\|\s*/,''),p=all(pm,'Point')[0];if(!p)continue;const tuple=all(p,'coordinates')[0]?.textContent.trim().split(',').map(Number);if(!tuple||tuple.length<2||!tuple.slice(0,2).every(Number.isFinite))continue;const matches=sites.flatMap(s=>s.addresses).filter(a=>norm(a)===norm(address));for(const a of matches){state.coords[a]=[tuple[1],tuple[0]];count++;}}if(!count)throw Error('KML ei sisaldanud sobiva aadressiga koordinaate.');save();renderMap(true);message(count+' kaardipunkti lisatud.');}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.plan){switchPlan(d.plan);return;}if(b.id==='weekend-sort'){weekendOrder(state.crews[active]);save();render();return;}if(d.machine!==undefined){active=Number(d.machine);render();}if(d.detail)openDetail(d.detail);if(d.add)add(d.add);if(d.remove){state.crews[active].stops=state.crews[active].stops.filter(s=>s.id!==d.remove);save();render();}if(d.up!==undefined||d.down!==undefined){let i=Number(d.up??d.down),j=i+(d.up!==undefined?-1:1),a=state.crews[active].stops;if(j>=0&&j<a.length){[a[i],a[j]]=[a[j],a[i]];save();render();}}if(b.id==='close')$('detail').close();if(b.id==='save-note'){state.notes[selected]=$('driver-note').value;save();$('detail').close();}if(b.id==='print')printSheet();if(b.id==='print-all')exportAll();if(b.id==='archive-routes')exportAll(true);if(b.id==='fit')renderMap(true);if(b.id==='backup')download('murumehed-masinaringid-'+new Date().toISOString().slice(0,10)+'.json',fullBackup());});
function fullBackup(){return JSON.stringify({...bundle,objects:{updated:window.MMData?.info?.updated||'',sites}},null,2);}
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='start-time'||el.id==='start-day'){state.crews[active][el.id==='start-time'?'startTime':'startDay']=el.value;save();}if(el.dataset.show!==undefined){shown[Number(el.dataset.show)]=el.checked;renderMap();}if(el.dataset.minutes){const n=el.value===''?null:Number(el.value);if(n!==null&&(!Number.isFinite(n)||n<0||n>1440))throw Error('Sisesta tööaeg 0–1440 min.');state.crews[active].stops.find(s=>s.id===el.dataset.minutes).minutes=n;save();renderMachines();renderRoute();}if(el.id==='crew-name'){if(!el.value.trim())throw Error('Masinal peab olema nimi.');state.crews[active].name=el.value.trim().slice(0,80);save();render();}if(['deadline','free','service-filter'].includes(el.id)){renderList();renderMap();}if(el.id==='unassigned')renderMap();if(el.id==='coords'&&el.files[0]){await importCoords(el.files[0]);el.value='';}if(el.id==='restore'&&el.files[0]){if(el.files[0].size>5e6)throw Error('Plaanifail on liiga suur.');const p=JSON.parse(await el.files[0].text());el.value='';if(window.MMData&&p&&(p.objects||Array.isArray(p.sites))){window.MMData.install(p,localStorage,()=>download('masinaringid-enne-taastamist.json',fullBackup()));location.reload();return;}const next=readPlan(p);download('masinaringid-enne-taastamist.json',fullBackup());bundle=next;state=bundle.plans[mode];seedCoords();active=0;save();render();renderMap(true);el.value='';}}catch(err){message(err.message);}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='start-time'){state.crews[active].startTime=el.value;save();return;}if(!el.dataset.minutes)return;const n=el.value===''?null:Number(el.value);if(n!==null&&(!Number.isFinite(n)||n<0||n>1440)){message('Sisesta tööaeg 0–1440 min.');return;}state.crews[active].stops.find(st=>st.id===el.dataset.minutes).minutes=n;save();renderMachines();renderSummary();});
$('search').oninput=()=>{renderList();renderMap();};let dragging=null;
$('route').addEventListener('dragstart',e=>{const row=e.target.closest('[data-drag]');if(row){dragging=Number(row.dataset.drag);e.dataTransfer.effectAllowed='move';}});
$('route').addEventListener('dragover',e=>e.preventDefault());$('route').addEventListener('drop',e=>{e.preventDefault();const row=e.target.closest('[data-drag]');if(row&&dragging!==null){const to=Number(row.dataset.drag),st=state.crews[active].stops.splice(dragging,1)[0];state.crews[active].stops.splice(to,0,st);dragging=null;save();render();}});
render();renderMap(true);message(restoreMessage||'Vali masin ja lisa objektid. Plaan salvestub automaatselt.');
})();

